// When a file or the project rolls up its lines, the first of these that any line has wins; with none, it is approved.
const ROLL_UP = ['changes-requested', 'needs-recording', 'needs-review'];
const emptyTally = () => ({ 'changes-requested': 0, 'needs-recording': 0, 'needs-review': 0, approved: 0 });

export default function createReviewBoard({ files }) {
  const lines = new Map();
  // Files in input order, each with its line ids in script order and its count of each status.
  const filesById = new Map();
  const projectTally = emptyTally();
  for (const file of files) {
    const tally = emptyTally();
    for (const lineId of file.lines) {
      lines.set(lineId, { fileTally: tally, status: 'needs-recording', version: 0 });
      tally['needs-recording'] += 1;
      projectTally['needs-recording'] += 1;
    }
    // A copy, so toReview keeps script order even if the caller reorders its array later.
    filesById.set(file.id, { lineIds: [...file.lines], tally });
  }

  const lineOf = (lineId) => {
    const line = lines.get(lineId);
    if (!line) throw new Error(`Unknown line: ${lineId}`);
    return line;
  };
  // After setup, the only place a status changes: the line leaves the count of the status it really had, in its file
  // and in the project.
  const setStatus = (line, status) => {
    line.fileTally[line.status] -= 1;
    projectTally[line.status] -= 1;
    line.fileTally[status] += 1;
    projectTally[status] += 1;
    line.status = status;
  };
  const rollUp = (tally) => ROLL_UP.find((status) => tally[status] > 0) ?? 'approved';
  // A review verdict counts only for the recording that is on the line now and still matches its text.
  const reviewable = (line, version) => version === line.version && (line.status === 'needs-review' || line.status === 'approved');

  return {
    record(lineId) {
      const line = lineOf(lineId);
      line.version += 1;
      setStatus(line, 'needs-review');
      return line.version;
    },
    edit(lineId) {
      setStatus(lineOf(lineId), 'needs-recording');
    },
    approve(lineId, version) {
      const line = lineOf(lineId);
      if (!reviewable(line, version)) return false;
      setStatus(line, 'approved');
      return true;
    },
    requestChanges(lineId, version) {
      const line = lineOf(lineId);
      if (!reviewable(line, version)) return false;
      setStatus(line, 'changes-requested');
      return true;
    },
    lineStatus(lineId) {
      return lineOf(lineId).status;
    },
    fileStatus(fileId) {
      const file = filesById.get(fileId);
      if (!file) throw new Error(`Unknown file: ${fileId}`);
      return rollUp(file.tally);
    },
    projectStatus() {
      return rollUp(projectTally);
    },
    toReview() {
      const result = [];
      for (const [fileId, file] of filesById) {
        if (file.tally['needs-review'] === 0) continue;
        result.push({ fileId, lineIds: file.lineIds.filter((lineId) => lineOf(lineId).status === 'needs-review') });
      }
      return result;
    },
  };
}
